CREATE TYPE "ClinicalTestResponseType" AS ENUM ('CATEGORICAL','NUMERIC','SCALE','OPTIONS','TEXT');
CREATE TABLE "clinical_protocols" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "clinical_protocols_pkey" PRIMARY KEY ("id"));
CREATE TABLE "clinical_test_definitions" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"response_type" "ClinicalTestResponseType" NOT NULL,"scale_min" DECIMAL(14,4),"scale_max" DECIMAL(14,4),"unit" TEXT,"options" JSONB,"is_selectable" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "clinical_test_definitions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "measurement_methods" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"is_selectable" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "measurement_methods_pkey" PRIMARY KEY ("id"));
CREATE TABLE "clinical_evaluations" ("id" UUID NOT NULL,"attention_id" UUID NOT NULL,"protocol_id" UUID,"body_area_or_type" TEXT NOT NULL,"conclusion" TEXT,"author_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"last_modified_by_id" UUID,"last_modified_at" TIMESTAMPTZ(6),CONSTRAINT "clinical_evaluations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "clinical_test_results" ("id" UUID NOT NULL,"evaluation_id" UUID NOT NULL,"test_definition_id" UUID NOT NULL,"measurement_method_id" UUID,"side" TEXT,"observation" TEXT,"value" JSONB NOT NULL,"definition_snapshot" JSONB NOT NULL,CONSTRAINT "clinical_test_results_pkey" PRIMARY KEY ("id"));
CREATE INDEX "clinical_evaluations_attention_id_idx" ON "clinical_evaluations"("attention_id");
ALTER TABLE "clinical_evaluations" ADD CONSTRAINT "ce_attention_fk" FOREIGN KEY ("attention_id") REFERENCES "clinical_attentions"("id") ON DELETE RESTRICT;
ALTER TABLE "clinical_test_results" ADD CONSTRAINT "ctr_eval_fk" FOREIGN KEY ("evaluation_id") REFERENCES "clinical_evaluations"("id") ON DELETE RESTRICT;
